import logging
import re
from taf.internal.aashell import AaShellFactory

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AashellCore(object):
    _aashell_factory = AaShellFactory()

    def create_aashell_cli(
            self,
            name,
            host=None,
            port=None,
            namespace=None,
            pod=None,
            hops=None,
            forwarding_port=None):
        """
        Create AaShell instance as per given parameters

        :param str name: alias name
        :param str host: (optional) telnet host of aashell, default value is "127.0.0.1". Avoid providing "host"
                        parameter, when "pod" + "namespace" is given.
        :param int port: (optional) telnet port of aashell, default value is 15007
        :param str namespace: (optional) kubernetes namespace for vCU/vDU
        :param str pod: (optional) kubernetes pod name for vCU/vDU
        :param dict hops: Proxy host details. This dict can be nested via another "proxy" entry. The top-level dict is
                          the hop, that is nearest to the final AaShell. The default entries for this top-level dict are
                          host='192.168.255.129', user='toor4nsn', password='oZPS0POrRieRtu' and port=22. It is possible
                          to specify a modified top-level dict by only giving the non-default entries and/or the
                          additional entry for "proxy".
        :param int forwarding_port: local port where port forwarding will be done
        """
        configuration = {}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["host", "port", "namespace", "pod", "hops", "forwarding_port"]:
                if parameter_value is not None:
                    configuration[parameter_name] = int(parameter_value) \
                        if parameter_name in ["port", "forwarding_port"] else parameter_value
        aashell = self._aashell_factory.create_aashell(**configuration)
        self.cache_command_output[name] = {}
        logger.info("Aashell CLI created successfully")
        self.set_alias(name, aashell)

    def execute_aashell_command(self, name, command, timeout=15, use_cache=True):
        if use_cache and command in self.cache_command_output[name]:
            logger.debug("Using '{}' command output from '{}' cache".format(command, name))
            return self.cache_command_output[name][command]
        else:
            managed_object = self.get_alias_value(name)
            output = managed_object.execute(
                command=command.encode('utf-8'),
                timeout=float(timeout)).decode('utf-8')
            if self._can_be_in_cache(command):
                logger.debug('Adding aashell command output in cache')
                self.cache_command_output[name][command] = output
            return output

    @staticmethod
    def _can_be_in_cache(command):
        return any(command.startswith(start) for start in ('help', 'nodes', 'getResourcesUsage -h'))

    def _assert_command_available_in_help(self, name, help_command, command):
        assert self._is_command_available_in_help(name, help_command, command), (
            "called AaShell function is not applicable as '{}' command is "
            "not supported in '{}' AaShell output").format(command, help_command)

    def _is_command_available_in_help(self, name, help_command, command):
        output = self.execute_aashell_command(name, help_command)
        return bool(re.search(r"^{}\b".format(command), output, re.MULTILINE))

    def _extract_process_node_suffixes(self, name, command):
        process_node_suffix = []
        if self._is_command_available_in_help(name, "help", "nodes"):
            for node, chunk in re.findall(
                    r"node: (\S+)((?:(?!node: ).)*{})".format(command),
                    self.execute_aashell_command(
                        name=name,
                        command='nodes -p -c {}'.format(command)),
                    re.DOTALL):
                process = re.findall(r"(\S+)\r?\nCommand\s", chunk)[-1]
                process_node_suffix.append(" @{process} #{node}".format(node=node, process=process))
        logger.debug("process_node suffix list:{}".format(process_node_suffix))
        return process_node_suffix or ['']
